mapper.select:
WITH T0 AS ( SELECT SALFCY_0 AS Site, YRNCBPS_0 AS SupplierCode, SRENUM_0 AS NCNo, YSREDAT_0 AS NCDate, YORIPJT_0 AS ProjectCode FROM EXPLOIT.SERREQUEST WHERE --- ONLY Customer Claim, NC entry, NC internal, NC final YSRE_CATEG_0 IN ('RCL','RNC','REN', 'RFN')
AND YSRE_CATEG_0 = #{NCCatCode}
AND YRNCBPS_0 = #{SupplierCode}
AND ( YSRE_DATNC_0 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_0 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_1 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_2 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_3 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_4 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_5 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_6 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_7 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_8 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_9 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_10 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_11 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) )
AND SALFCY_0 IN ('ZHU','HKG','YSH')
AND SALFCY_0 = #{Site}
)
SELECT COUNT(1) AS Cnt FROM T0

WITH T0 AS ( SELECT SALFCY_0 AS Site, YRNCBPS_0 AS SupplierCode, SRENUM_0 AS NCNo, YSREDAT_0 AS NCDate, YORIPJT_0 AS ProjectNO, SRETTR_0 AS PN, SREDES_0 AS Description, IIF(YSRE_DATNC_0 = '1753-01-01', NULL, YSRE_DATNC_0) AS NCDAT0, IIF(YSRE_DATNC_1 = '1753-01-01', NULL, YSRE_DATNC_1) AS NCDAT1, IIF(YSRE_DATNC_2 = '1753-01-01', NULL, YSRE_DATNC_2) AS NCDAT2, IIF(YSRE_DATNC_3 = '1753-01-01', NULL, YSRE_DATNC_3) AS NCDAT3, IIF(YSRE_DATNC_4 = '1753-01-01', NULL, YSRE_DATNC_4) AS NCDAT4, IIF(YSRE_DATNC_5 = '1753-01-01', NULL, YSRE_DATNC_5) AS NCDAT5, IIF(YSRE_DATNC_6 = '1753-01-01', NULL, YSRE_DATNC_6) AS NCDAT6, IIF(YSRE_DATNC_7 = '1753-01-01', NULL, YSRE_DATNC_7) AS NCDAT7, IIF(YSRE_DATNC_8 = '1753-01-01', NULL, YSRE_DATNC_8) AS NCDAT8, IIF(YSRE_DATNC_9 = '1753-01-01', NULL, YSRE_DATNC_9) AS NCDAT9, IIF(YSRE_DATNC_10 = '1753-01-01', NULL, YSRE_DATNC_10) AS NCDAT10, IIF(YSRE_DATNC_11 = '1753-01-01', NULL, YSRE_DATNC_11) AS NCDAT11, IIF(YSRE_CATNC_0 = ' ', NULL, YSRE_CATNC_0) AS NCCAT0, IIF(YSRE_CATNC_1 = ' ', NULL, YSRE_CATNC_1) AS NCCAT1, IIF(YSRE_CATNC_2 = ' ', NULL, YSRE_CATNC_2) AS NCCAT2, IIF(YSRE_CATNC_3 = ' ', NULL, YSRE_CATNC_3) AS NCCAT3, IIF(YSRE_CATNC_4 = ' ', NULL, YSRE_CATNC_4) AS NCCAT4, IIF(YSRE_CATNC_5 = ' ', NULL, YSRE_CATNC_5) AS NCCAT5, IIF(YSRE_CATNC_6 = ' ', NULL, YSRE_CATNC_6) AS NCCAT6, IIF(YSRE_CATNC_7 = ' ', NULL, YSRE_CATNC_7) AS NCCAT7, IIF(YSRE_CATNC_8 = ' ', NULL, YSRE_CATNC_8) AS NCCAT8, IIF(YSRE_CATNC_9 = ' ', NULL, YSRE_CATNC_9) AS NCCAT9, IIF(YSRE_CATNC_10 = ' ', NULL, YSRE_CATNC_10) AS NCCAT10, IIF(YSRE_CATNC_11 = ' ', NULL, YSRE_CATNC_11) AS NCCAT11, IIF(YSRE_TYPNC_0 = ' ', NULL, YSRE_TYPNC_0) AS NCTYP0, IIF(YSRE_TYPNC_1 = ' ', NULL, YSRE_TYPNC_1) AS NCTYP1, IIF(YSRE_TYPNC_2 = ' ', NULL, YSRE_TYPNC_2) AS NCTYP2, IIF(YSRE_TYPNC_3 = ' ', NULL, YSRE_TYPNC_3) AS NCTYP3, IIF(YSRE_TYPNC_4 = ' ', NULL, YSRE_TYPNC_4) AS NCTYP4, IIF(YSRE_TYPNC_5 = ' ', NULL, YSRE_TYPNC_5) AS NCTYP5, IIF(YSRE_TYPNC_6 = ' ', NULL, YSRE_TYPNC_6) AS NCTYP6, IIF(YSRE_TYPNC_7 = ' ', NULL, YSRE_TYPNC_7) AS NCTYP7, IIF(YSRE_TYPNC_8 = ' ', NULL, YSRE_TYPNC_8) AS NCTYP8, IIF(YSRE_TYPNC_9 = ' ', NULL, YSRE_TYPNC_9) AS NCTYP9, IIF(YSRE_TYPNC_10 = ' ', NULL, YSRE_TYPNC_10) AS NCTYP10, IIF(YSRE_TYPNC_11 = ' ', NULL, YSRE_TYPNC_11) AS NCTYP11, CASE WHEN YSRE_CRIT_0=2 THEN 'Minor' WHEN YSRE_CRIT_0=3 THEN 'Major' ELSE NULL END AS NCCRIT0, CASE WHEN YSRE_CRIT_1=2 THEN 'Minor' WHEN YSRE_CRIT_1=3 THEN 'Major' ELSE NULL END AS NCCRIT1, CASE WHEN YSRE_CRIT_2=2 THEN 'Minor' WHEN YSRE_CRIT_2=3 THEN 'Major' ELSE NULL END AS NCCRIT2, CASE WHEN YSRE_CRIT_3=2 THEN 'Minor' WHEN YSRE_CRIT_3=3 THEN 'Major' ELSE NULL END AS NCCRIT3, CASE WHEN YSRE_CRIT_4=2 THEN 'Minor' WHEN YSRE_CRIT_4=3 THEN 'Major' ELSE NULL END AS NCCRIT4, CASE WHEN YSRE_CRIT_5=2 THEN 'Minor' WHEN YSRE_CRIT_5=3 THEN 'Major' ELSE NULL END AS NCCRIT5, CASE WHEN YSRE_CRIT_6=2 THEN 'Minor' WHEN YSRE_CRIT_6=3 THEN 'Major' ELSE NULL END AS NCCRIT6, CASE WHEN YSRE_CRIT_7=2 THEN 'Minor' WHEN YSRE_CRIT_7=3 THEN 'Major' ELSE NULL END AS NCCRIT7, CASE WHEN YSRE_CRIT_8=2 THEN 'Minor' WHEN YSRE_CRIT_8=3 THEN 'Major' ELSE NULL END AS NCCRIT8, CASE WHEN YSRE_CRIT_9=2 THEN 'Minor' WHEN YSRE_CRIT_9=3 THEN 'Major' ELSE NULL END AS NCCRIT9, CASE WHEN YSRE_CRIT_10=2 THEN 'Minor' WHEN YSRE_CRIT_10=3 THEN 'Major' ELSE NULL END AS NCCRIT10, CASE WHEN YSRE_CRIT_11=2 THEN 'Minor' WHEN YSRE_CRIT_11=3 THEN 'Major' ELSE NULL END AS NCCRIT11, IIF(YSRE_DES_0 = ' ', NULL, YSRE_DES_0) AS NCDES0, IIF(YSRE_DES_1 = ' ', NULL, YSRE_DES_1) AS NCDES1, IIF(YSRE_DES_2 = ' ', NULL, YSRE_DES_2) AS NCDES2, IIF(YSRE_DES_3 = ' ', NULL, YSRE_DES_3) AS NCDES3, IIF(YSRE_DES_4 = ' ', NULL, YSRE_DES_4) AS NCDES4, IIF(YSRE_DES_5 = ' ', NULL, YSRE_DES_5) AS NCDES5, IIF(YSRE_DES_6 = ' ', NULL, YSRE_DES_6) AS NCDES6, IIF(YSRE_DES_7 = ' ', NULL, YSRE_DES_7) AS NCDES7, IIF(YSRE_DES_8 = ' ', NULL, YSRE_DES_8) AS NCDES8, IIF(YSRE_DES_9 = ' ', NULL, YSRE_DES_9) AS NCDES9, IIF(YSRE_DES_10 = ' ', NULL, YSRE_DES_10) AS NCDES10, IIF(YSRE_DES_11 = ' ', NULL, YSRE_DES_11) AS NCDES11, IIF(YSRE_USRNC_0 = ' ', NULL, YSRE_USRNC_0) AS CreatedBy0, IIF(YSRE_USRNC_1 = ' ', NULL, YSRE_USRNC_1) AS CreatedBy1, IIF(YSRE_USRNC_2 = ' ', NULL, YSRE_USRNC_2) AS CreatedBy2, IIF(YSRE_USRNC_3 = ' ', NULL, YSRE_USRNC_3) AS CreatedBy3, IIF(YSRE_USRNC_4 = ' ', NULL, YSRE_USRNC_4) AS CreatedBy4, IIF(YSRE_USRNC_5 = ' ', NULL, YSRE_USRNC_5) AS CreatedBy5, IIF(YSRE_USRNC_6 = ' ', NULL, YSRE_USRNC_6) AS CreatedBy6, IIF(YSRE_USRNC_7 = ' ', NULL, YSRE_USRNC_7) AS CreatedBy7, IIF(YSRE_USRNC_8 = ' ', NULL, YSRE_USRNC_8) AS CreatedBy8, IIF(YSRE_USRNC_9 = ' ', NULL, YSRE_USRNC_9) AS CreatedBy9, IIF(YSRE_USRNC_10 = ' ', NULL, YSRE_USRNC_10) AS CreatedBy10, IIF(YSRE_USRNC_11 = ' ', NULL, YSRE_USRNC_11) AS CreatedBy11 FROM EXPLOIT.SERREQUEST INNER JOIN EXPLOIT.BPSUPPLIER BPSUPPLIER ON BPSUPPLIER.BPSNUM_0 = SERREQUEST.YRNCBPS_0 WHERE --- ONLY RCL[Customer Claim], REN[NC entry], RNC[NC internal], RFN[NC final] YSRE_CATEG_0 IN ('RCL','RNC','REN','RFN')
AND YSRE_CATEG_0 = #{NCCatCode}
AND YRNCBPS_0 = #{SupplierCode}
AND ( YSRE_DATNC_0 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_0 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_1 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_2 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_3 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_4 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_5 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_6 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_7 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_8 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_9 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_10 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) OR YSRE_DATNC_11 BETWEEN CONVERT(datetime, #{DateFrom} ,120) AND CONVERT(datetime, #{DateTo} ,120) )
AND SALFCY_0 IN ('ZHU','HKG','YSH')
AND SALFCY_0 = #{Site}
)
SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY NCDate ASC, NCNo ASC) AS ItemNO, * FROM T0 ORDER BY ItemNO ASC
OFFSET #{Offset} ROWS FETCH NEXT #{Limit} ROWS ONLY
